(() => {
const root=document.querySelector('[data-arena]');if(!root)return;
const get=s=>root.querySelector(s), api=root.dataset.api;let last=null, connected=false, previous=new Map();
const labels={ready:'READY',preparing:'PREPARING',running:'RUNNING',paused:'PAUSED',checking:'CHECKING',draining:'FINAL FLAG WINDOW',finished:'FINISHED',archived:'ARCHIVED',recreating:'RESETTING'};
function timer(){const el=get('[data-timer]');if(!last||!connected){el.textContent='—';return;}if(!['running','draining'].includes(last.phase)||!last.deadline){el.textContent=labels[last.phase]||'—';return;}const left=Math.max(0,Math.ceil(last.deadline-Date.now()/1000));el.textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');el.classList.toggle('urgent',left<=20);get('[data-progress]').value=Math.max(0,(last.tick_seconds||120)-left);get('[data-progress]').max=last.tick_seconds||120;}
async function refresh(){try{const responses=await Promise.all(['tick-status','teams'].map(p=>fetch(api+p+(api.startsWith('/api/')?'/':''),{cache:'no-store',signal:AbortSignal.timeout(7000)})));if(responses.some(r=>!r.ok))throw Error();const [d,teams]=await Promise.all(responses.map(r=>r.json()));if(d.mode!=='round1'||!Array.isArray(d.scores))throw Error();last=d;connected=true;root.classList.remove('disconnected');get('[data-live]').textContent='LIVE DATA CONNECTED';get('[data-phase]').textContent=labels[d.phase]||d.phase;get('[data-tick]').textContent=`Round ${d.round} / Tick ${d.tick}/${d.ticks_per_round}`;get('[data-updated]').textContent='Cập nhật lúc '+new Date().toLocaleTimeString('vi-VN');const rows=[...d.scores].sort((a,b)=>b.total-a.total||a.name.localeCompare(b.name));const body=get('[data-ranking]');body.replaceChildren();let rank=0;rows.forEach((team,i)=>{if(i===0||team.total!==rows[i-1].total)rank=i+1;const tr=document.createElement('tr');tr.classList.toggle('leader',rank===1);if(previous.has(team.team_id)&&previous.get(team.team_id)!==team.total)tr.classList.add('changed');[rank,team.name,team.total,`${team.sla} / ${d.ticks_per_round}`,team.attack,team.defense].forEach((v,index)=>{const td=document.createElement('td');td.textContent=String(v);if(index===5&&team.defense<0)td.className='negative';tr.append(td)});body.append(tr);previous.set(team.team_id,team.total)});if(!rows.length){const tr=body.insertRow();const td=tr.insertCell();td.colSpan=6;td.textContent='Chưa có đội đang hoạt động.';}timer();}catch(_){connected=false;root.classList.add('disconnected');get('[data-live]').textContent='LIVE DATA DISCONNECTED';if(!last)get('[data-ranking]').textContent='Chưa lấy được dữ liệu ForcAD. Đang thử kết nối lại…';timer();}finally{setTimeout(refresh,5000)}}
refresh();setInterval(timer,1000);
})();
;(() => {
 if(location.pathname!=='/' || !document.body.classList.contains('arena-admin'))return;
 const root=document.querySelector('[data-arena]');
 const area=document.createElement('section');area.className='arena-detail';area.hidden=true;
 root.append(area);
 const statuses={101:'UP',102:'CORRUPT',103:'MUMBLE',104:'DOWN',110:'CHECK FAILED','-1':'NOT CHECKED'};
 let seen=new Set(), initialized=false;
 const node=(tag,text)=>{const el=document.createElement(tag);if(text!==undefined)el.textContent=String(text);return el};
 function table(title,heads,rows){const box=node('div');box.className='arena-board';const t=node('table');t.append(node('caption',title));const thead=node('thead'),tr=node('tr');heads.forEach(h=>tr.append(node('th',h)));thead.append(tr);t.append(thead);const body=node('tbody');rows.forEach(values=>{const row=node('tr');values.forEach(v=>row.append(node('td',v)));body.append(row)});if(!rows.length){const row=node('tr'),td=node('td','Chưa có dữ liệu.');td.colSpan=heads.length;row.append(td);body.append(row)}t.append(body);box.append(t);return box}
 async function refresh(){try{const r=await fetch('/api/admin/arena/',{credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(7000)});if(r.status===401||r.status===403){area.hidden=true;return}if(!r.ok)throw Error();const d=await r.json();area.hidden=false;area.replaceChildren();
 const nodes=node('div');nodes.className='arena-nodes';const grouped=new Map();d.services.forEach(s=>{if(!grouped.has(s.team_id))grouped.set(s.team_id,[]);grouped.get(s.team_id).push(s)});
 grouped.forEach((services,id)=>{const card=node('article');card.className='arena-node';card.append(node('h3',services[0].team));services.forEach(s=>{const text=node('p',s.service+' · '+(statuses[s.status]||'UNKNOWN'));text.className=s.status===101?'service-up':'service-down';card.append(text)});nodes.append(card)});area.append(node('h2','Service arena'),nodes);
 const feed=node('div');feed.className='arena-feed';feed.append(node('h2','Capture feed'));if(!d.captures.length)feed.append(node('p','Chưa có capture được ghi nhận.'));
 const current=new Set();d.captures.forEach(c=>{const key=c.attacker_id+':'+c.capture_flag_id;current.add(key);const row=node('p',`Tick ${c.tick} · ${c.attacker} → ${c.victim} · ${c.service} · ${c.submit_time}`);if(initialized&&!seen.has(key))row.className='changed';feed.append(row)});seen=current;initialized=true;area.append(feed);
 area.append(table('Kết quả checker cuối tick',['Round','Tick','Đội','Trạng thái','SLA'],d.checks.map(c=>[1,c.tick,c.team,statuses[c.status]||'UNKNOWN',c.points])));
 area.append(node('p','Trạng thái service là kết quả checker gần nhất. Lịch sử SLA được lưu theo đội/tick; backend hiện không lưu timestamp hay từng service cho bản ghi này.'));
 }catch(_){area.hidden=false;let warning=area.querySelector('[data-detail-error]');if(!warning){warning=node('p');warning.dataset.detailError='true';area.prepend(warning)}warning.textContent='LIVE DATA DISCONNECTED · Chi tiết admin chưa cập nhật được; giữ dữ liệu gần nhất.';}finally{setTimeout(refresh,5000)}}refresh();
})();
